    {**rule, **classification_by_id[rule["source_rule_id"]]}
    for rule in inventory["rules"]
]

print(
    json.dumps(
        {
            "comparison": comparison,
            "inventory": inventory,
            "classified_inventory_in_canonical_order": classified_inventory,
        },
        indent=2,
        sort_keys=True,
    )
)

